def get_coeffs_fixed(k_max, n_initial):
    # coeffs[k][j] is a list of coefficients for a_{0,i}
    # a_{k,j} = sum_{i=0}^{n_initial-1} coeffs[k][j][i] * a_{0,i}
    coeffs = []
    # k=0
    k0 = []
    for j in range(n_initial):
        c = [0] * n_initial
        c[j] = 1
        k0.append(c)
    coeffs.append(k0)

    for k in range(1, k_max + 1):
        prev_k = coeffs[k-1]
        curr_k = []
        # Number of terms after k steps: (n_initial - 1) * 2^k + 1
        num_terms = (n_initial - 1) * (2**k) + 1
        for j in range(num_terms):
            if j % 2 == 0:
                # a_{k, 2j} = a_{k-1, j}
                curr_k.append(prev_k[j // 2])
            else:
                # a_{k, 2j+1} = a_{k-1, j} + a_{k-1, j+1}
                c1 = prev_k[j // 2]
                c2 = prev_k[j // 2 + 1]
                curr_k.append([c1[i] + c2[i] for i in range(n_initial)])
        coeffs.append(curr_k)
    return coeffs

