def solve():
    # A_{k, r} m + B_{k, r} = 2013 for m in {0, ..., 999}
    # Max possible A and B is 2013 (since m >= 0 and A, B >= 1)
    # Exception: if m = 0, then B = 2013, A can be anything.
    # But if m = 0, we need B = 2013. 
    # If m > 0, then A = (2013 - B) / m. Since B >= 1, A <= 2012.
    # So A, B are bounded by 2013.

    # dp[A][B] = count of r < 2^k
    dp = {}
    # Initial state k=1:
    # r=0: A=1, B=1
    # r=1: A=2, B=3
    dp[(1, 1)] = 1
    dp[(2, 3)] = 1

    for k in range(2, 2014):
        new_dp = {}
        for (A, B), count in dp.items():
            # r = 2p: A_new = A, B_new = B
            new_dp[(A, B)] = new_dp.get((A, B), 0) + count
            # r = 2p+1: A_new = 2A, B_new = A + 2B
            nA, nB = 2 * A, A + 2 * B
            if nA <= 2013 and nB <= 2013:
                new_dp[(nA, nB)] = new_dp.get((nA, nB), 0) + count
        dp = new_dp

    total_count = 0
    for (A, B), count in dp.items():
        for m in range(1000):
            if A * m + B == 2013:
                total_count += count
    return total_count

